interface PageProps {
  type: 'resizer' | 'compress' | 'converter' | 'empty-lines' | 'line-breaks' | 'duplicate-lines' | 'pending-tool';
  resizerPage?: { slug: string; introCopy?: string } | null;
  compressPreset?: { slug: string; introDescription?: string } | null;
  converterPreset?: { slug: string; introCopy?: string; seoContext?: string } | null;
  emptyLinesPreset?: { intentCard?: string; [key: string]: any } | null;
  lineBreaksPreset?: { intentDescription?: string; [key: string]: any } | null;
  duplicateLinesPreset?: { intentCard?: string; [key: string]: any } | null;
  pendingTool?: any;
}

export function getPresetIntentDescription(props: PageProps): string {
  if (props.type === 'converter' && props.converterPreset) {
    const slug = props.converterPreset.slug;
    if (CONVERTER_INTENT_MAP[slug]) {
      return CONVERTER_INTENT_MAP[slug];
    }
    return props.converterPreset.seoContext || props.converterPreset.introCopy || '';
  }

  if (props.type === 'compress' && props.compressPreset) {
    const slug = props.compressPreset.slug;
    if (COMPRESS_INTENT_MAP[slug]) {
      return COMPRESS_INTENT_MAP[slug];
    }
    return props.compressPreset.introDescription || '';
  }

  if (props.type === 'resizer' && props.resizerPage) {
    const slug = props.resizerPage.slug;
    if (RESIZER_INTENT_MAP[slug]) {
      return RESIZER_INTENT_MAP[slug];
    }
    if (props.resizerPage.introCopy) {
      return props.resizerPage.introCopy.replace(/<[^>]*>/g, '');
    }
  }

  if (props.type === 'empty-lines' && props.emptyLinesPreset) {
    return props.emptyLinesPreset.intentCard || '';
  }

  if (props.type === 'line-breaks' && props.lineBreaksPreset) {
    return props.lineBreaksPreset.intentDescription || '';
  }

  if (props.type === 'duplicate-lines' && props.duplicateLinesPreset) {
    return props.duplicateLinesPreset.intentCard || '';
  }

  return '';
}
